from pathlib import Path
import re
for f in Path('verification').glob('*.txt'):
 if 'page' in f.name:continue
 for i,p in enumerate(f.read_text().split('\\f'),1):
  titles=[l.strip() for l in p.splitlines() if re.match(r'表\\s*(?:5|12|14|16|22|29|44|45|50|59|60|61)\\s',l)]
  if (f.name.startswith('shibo_22') and titles) or (f.name.startswith(('shibo_19','shibo_21')) and any(re.match(r'表\\s*(5|22)\\s',t) for t in titles)):
   print(f.name,'PDF',i,'末尾',repr(p.strip().splitlines()[-1]),titles)
