from pathlib import Path
import re,json
root=Path(__file__).parent
s=(root/'shibo_22_kobetsu.txt').read_text()
def table(n):
 m=re.search(r'"'^表'"\\s*'+str(n)+r'\\s',s,re.M)
 end=re.search(r'"'^表'"\\s*\\d+\\s',s[m.end():],re.M)
 return s[m.start():m.end()+end.start()] if end else s[m.start():]
def pairs(line):return [tuple(map(int,p)) for p in re.findall(r'(\\d+)\\s*\\((\\d+)\\)',line)]
def rows(n):return [(l,pairs(l)) for l in table(n).splitlines() if pairs(l)]
def total(ps):return tuple(map(sum,zip(*ps)))
result={}
for n,col in [(12,0),(14,4),(16,0),(22,0),(29,0),(44,1),(45,1),(50,1),(59,0),(60,0),(61,0)]:
 result[str(n)]={'rows':[{'text':l,'pairs':p} for l,p in rows(n)]}
 if n in (14,16):
  a=[]
  for l,p in rows(n):
   if '小計' in l:break
   a.append(p[col])
  result[str(n)]['sum_before_subtotal']=total(a)
 if n in (12,44,45,59):
  a=[p[col] for l,p in rows(n) if not re.search(r'計\\s',l)]
  result[str(n)]['sum_rows_excluding_total']=total(a)
 if n==22: result[str(n)]['sum_two_rows']=total([p[0] for l,p in rows(n) if '実施なし' in l or '実施あり' in l])
 if n==29:
  a=[];started=False
  for l,p in rows(n):
   if '小計' in l:break
   if '認可保育所' in l:started=True
   if started:a.append(p[0])
  result[str(n)]['sum_institution_details']=total(a)
result['arithmetic']={'Q1_deltas': [164-157,5-1,349-338,186-179,405-394,201-194,430-419], 'Q1_link':173+6,'Q3_percent':12.0+82.0,'Q4_percent':[0+12.5+0+0+37.5,12.5+12.5+12.5+0+25.0], 'Q4_involved':5+3,'Q5_percent':69.4+28.6}
(root/'checks.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\\n')
for n,v in result.items():
 print(n,{k:x for k,x in v.items() if k"'!='"'rows'} if n"'!='"'arithmetic' else v)
